import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { useIsMobile } from "@/registry/erbium/hooks/use-is-mobile";
export default function Demo() {
  const isMobile = useIsMobile();
  return (
    <p aria-live="polite">
      Viewport: {isMobile ? "mobile" : "desktop"}. Resize the window to update.
    </p>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/use-is-mobile-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  parameters: {
    layout: "centered",
    docs: { description: { component: "## Usage\n\nTracks whether the viewport is narrower than 48rem. Resize your browser to update the example. The default server value is false.\n\nImport `useIsMobile` from `@/registry/erbium/hooks/use-is-mobile`." } },
  },
} satisfies Meta;

export default { ...meta, title: "Hooks/Use Is Mobile",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/use-is-mobile-demo";

const Example = () => <Demo />;

export default Example;
